(async()=>{const slots=[...document.querySelectorAll('[data-fragment]')];try{await Promise.all(slots.map(async slot=>{const r=await fetch(slot.dataset.fragment,{credentials:'same-origin'});if(!r.ok)throw new Error(slot.dataset.fragment+' '+r.status);slot.outerHTML=await r.text()}));const hero=document.querySelector('[data-hero-image]');if(hero)hero.src='data:image/webp;base64,'+(window.__MAI_HERO||[]).join('');const s=document.createElement('script');s.src='assets/montrealai-omega-v3/site.js';s.defer=true;document.body.appendChild(s)}catch(e){console.error(e);document.querySelectorAll('[data-fragment]').forEach(slot=>slot.innerHTML='<section class="section light"><div class="container"><p>Institutional module unavailable. Use the public Proof Room links above.</p></div></section>')}})();